//import { StrictMode } from 'react'
import './index.css'
import App from './App.tsx'

// We want to make some modules globally available, so that our apps/libraries can consume them from there, instead of every app having to bundle its own "react"
// index.html's <head> import map grabs those modules when an app imports them, and redirects them to our window values.
// The import map is generated by vite.config.ts from shared-modules.js at build time.

import * as React from 'react';
import * as ReactDOM from 'react-dom';
import * as ReactDOMClient from 'react-dom/client';
import * as ReactJSXRuntime from 'react/jsx-runtime';
import * as ReactCompilerRuntime from 'react/compiler-runtime';
import { SHARED_MODULES } from '../shared-modules.js';

// The Record type makes TypeScript report a missing global when SHARED_MODULES changes.
const sharedGlobals: Record<(typeof SHARED_MODULES)[number]['global'], unknown> = {
    React,
    ReactDOM,
    ReactDOMClient,
    ReactJSXRuntime,
    ReactCompilerRuntime,
};

for (const { global } of SHARED_MODULES) {
    (window as any)[global] = sharedGlobals[global];
}

import './Backend/MessageRouter.ts'; // Must be in so it sets the globally accessible prototype
import './Backend/Notifications.ts'; // Sets window.Notifications before any app can show one
import './Backend/PanelDirectory.ts'; // Sets window.PanelDirectory before any panel mounts
import './Backend/AppApi.ts'; // Sets window.AppApi before any app registers its API
import './Panels/PanelContext.ts'; // Sets window.TacPhoneUtils.PanelContext/usePanel
import './Panels/PanelHost.tsx'; // Tab <-> PanelInstance binding

ReactDOMClient.createRoot(document.getElementById('root')!).render(

    // StrictMode messes up everything. Every app actually gets created twice, because its constructor and componentDidMount methods are called twice, which duplicates all our apps.
  //<StrictMode>
    <App/>
  //</StrictMode>,
)
